// switchView changes the current view
func (a *App) switchView(view command.ViewType) tea.Cmd {
	if view != a.currentView {
		if cmd, ok := a.settleCurrentView(); !ok {
			return cmd
		}
	}

	// Lazy loading of views
	if _, exists := a.views[view]; !exists {
		a.createView(view)
	}

	a.currentView = view

	newView, ok := a.views[view]
	if !ok {
		return nil
	}
	log.Printf("Switching to view: %s, calling Init()", view)

	// Init() + a WindowSizeMsg to force the resize, plus the snapshot of
	// work in progress: the view was kept up to date for as long as it
	// existed, but a view built just now was not there for anything that had
	// already started.
	return tea.Batch(newView.Init(), a.requestResize(), a.enterView(view))
}

// settleCurrentView gives the view being left the chance to write down what it
	if newFooterHeight := a.getFooterHeight(); newFooterHeight != a.lastFooterHeight {
		a.resize(a.width, a.height)
	}
	return tea.Batch(cmds...)
}

// enterView hands a view that is entering the screen the snapshot and the
// current frame. Every path that installs a view without going through
// switchView calls it too, otherwise the view shows stale rows until the next
// change.
func (a *App) enterView(target command.ViewType) tea.Cmd {
	return tea.Batch(a.sendJobsTo(target), a.sendFrameTo(target))
}

// sendJobsTo hands the snapshot to one view, which is what a view entering the
// screen needs: it was updated where it stood, but a view built lazily on the
// way in was not there for any of it.
func (a *App) sendJobsTo(target command.ViewType) tea.Cmd {
	view, ok := a.views[target]
	if !ok {
		return nil
	}
	updated, cmd := view.Update(a.changedMsg())
	a.setView(target, updated)
	return cmd
}
